from decimal import Decimal, InvalidOperation


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _as_decimal(value) -> Decimal:
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise BusinessRuleViolation("E5001", "Discount out of range") from None


def set_discount(order: dict, pct, user_id: str, users: list[dict]) -> dict:
    discount = _as_decimal(pct)

    try:
        in_range = Decimal("0") <= discount <= Decimal("100")
    except InvalidOperation:
        in_range = False

    if not in_range:
        raise BusinessRuleViolation("E5001", "Discount out of range")

    if discount > Decimal("20"):
        role = ""
        for user in users:
            if user.get("USR_ID") == user_id and user.get("DEL_FLG", "") != "Y":
                role = user.get("ROLE_ID", "")
                break

        if role not in ("MGR", "ADMIN"):
            raise BusinessRuleViolation(
                "E5002",
                "Discount over 20 percent requires manager role",
            )

    updated_order = dict(order)
    updated_order["DISC_PCT"] = pct
    return updated_order
